[[nodiscard]] constexpr const std::array<uint8_t, 256>& get_ebcdic_table(EbcdicCodepage cp) noexcept {
    switch (cp) {
        case EbcdicCodepage::CP1047: return EBCDIC_CP1047;
        case EbcdicCodepage::CP500:  return EBCDIC_CP500;
        default:                     return EBCDIC_CP037;
    }
}

